	// Rare moments: the dice, the next preview forced rare, and how many you've seen this session.
	private final Random random = new Random();
	private volatile boolean forceRare;
	private volatile int rareCount;
	// The rare moments log for the account you're on, and which account it belongs to.
	private volatile RareLog rareLog = new RareLog();
	private String rareProfile;
	private volatile String status = "";
	private volatile String hint = "";
	private volatile int statusCount;
	private volatile int statusCap;

	/**
	 * One pile beside the resource it came from: where it is, which way it's turned, and how full.
	 */
	private static final class Pile
	{
		final int id;
		final Activity activity;
		final String key;
		final double x;
		final double y;
		final int plane;
		final int view;
		final int yaw;
		// How spread out it is: 1 on land, closer on a boat.
		final double spread;
		int count;
		double lastUsed;
		// The last item that landed on it, for the hover label.
		String name = "";

		Pile(int id, Activity activity, String key, double x, double y, int plane, int view, int yaw, double spread)
		{
			this.id = id;
			this.activity = activity;
			this.key = key;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.view = view;
			this.yaw = yaw;
			this.spread = spread;
		}
	}

	/**
	 * An item that arrived in the inventory, with what left it in the same change. When nothing
	 * arrived, each item that left is recorded with used set, for Firemaking.
	 */
	static final class Gain
	{
		final int itemId;
		final int quantity;
		final int tick;
		final List<Integer> lost;
		final boolean used;

		Gain(int itemId, int quantity, int tick, List<Integer> lost, boolean used)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.tick = tick;
			this.lost = lost;
			this.used = used;
		}
	}

	@Provides
	ImmersiveSkillingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ImmersiveSkillingConfig.class);
	}

	@Override
	protected void startUp()
	{
		props = new Props(client);
		overlay.clear();
		overlayManager.add(overlay);
		panel = new ImmersiveSkillingPanel(this, config, configManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Immersive Skilling")
			.icon(icon)
			.priority(9)
			.panel(panel)
			.build();
		if (config.showPanel())
		{
			clientToolbar.addNavigation(navButton);
		}
		resetState();
		lastItem.clear();
		lastItem.put(Skill.WOODCUTTING, config.lastWoodcutting());
		lastItem.put(Skill.FISHING, config.lastFishing());
		lastItem.put(Skill.MINING, config.lastMining());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		Props toClear = props;
		clientThread.invokeLater(() ->
		{
			if (toClear != null)
			{
				toClear.shutDown();
			}
			overlay.clear();
		});
		pending.clear();
	}

	private void resetState()
	{
		lastInventory = null;
		lastXp.clear();
		lastLevel.clear();
		sourceSeen = null;
		xpTick.clear();
		matchedXp.clear();
		checkedXp.clear();
		pending.clear();
		piles.clear();
		lastPile = null;
		lastActivity = null;
		status = "";
		hint = "";
		statusCount = 0;
		statusCap = 0;
	}

	// ---- Events ----------------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			return;
		}
		// Logging out, hopping or loading a new area: local positions are no longer valid.
		clearAll();
		if (state == GameState.LOADING)
		{
			// Only the area changed, not your XP or inventory. Forgetting them here made the first
			// item after every map load (crossing a region, sailing on) play nothing.
			return;
		}
		resetState();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int xp = event.getXp();
		Integer before = lastXp.put(skill, xp);
		Integer levelBefore = lastLevel.put(skill, event.getLevel());
		if (levelBefore != null && event.getLevel() > levelBefore && config.levelUpMoments())
		{
			levelUp(skill, event.getLevel());
		}
		if (before != null && xp > before)
		{
			xpTick.put(skill, client.getTickCount());
			if (skill == Skill.AGILITY)
			{
				// Agility gives no item: the XP itself says you cleared an obstacle.
				agility(xp - before);
			}
			match();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			// Everything that was or is worn now was just swapped, so it's not a product.
			int tick = client.getTickCount();
			Set<Integer> worn = counts(event.getItemContainer()).keySet();
			for (int id : lastWorn)
			{
				wornChanged.put(id, tick);
			}
			for (int id : worn)
			{
				wornChanged.put(id, tick);
			}
			lastWorn = new HashSet<>(worn);
			return;
		}
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		Map<Integer, Integer> now = counts(event.getItemContainer());
		Map<Integer, Integer> before = lastInventory;
		lastInventory = now;
		if (before == null)
		{
			return;
		}
		List<Integer> lost = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : before.entrySet())
		{
			if (now.getOrDefault(e.getKey(), 0) < e.getValue())
			{
				lost.add(e.getKey());
			}
		}
		int tick = client.getTickCount();
		List<String> lostNames = new ArrayList<>();
		for (int id : lost)
		{
			lostNames.add(client.getItemDefinition(id).getName());
		}
		boolean anyGained = false;
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			int gained = e.getValue() - before.getOrDefault(e.getKey(), 0);
			if (gained > 0 && isSip(client.getItemDefinition(e.getKey()).getName(), lostNames))
			{
				// Drinking a dose isn't making a potion (issue #6).
				anyGained = true;
				continue;
			}
			if (gained > 0)
			{
				sackHaul(e.getKey(), gained, tick);
				burnt(e.getKey(), gained);
				pending.add(new Gain(e.getKey(), gained, tick, lost, false));
				anyGained = true;
			}
		}
		if (!anyGained)
		{
			// Nothing arrived: maybe pay-dirt went into the hopper, or a log onto a fire.
			for (int id : lost)
			{
				deposit(id, before.get(id) - now.getOrDefault(id, 0), tick);
			}
			for (int id : lost)
			{
				pending.add(new Gain(id, before.get(id) - now.getOrDefault(id, 0), tick, Collections.emptyList(), true));
			}
		}
		match();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		pending.removeIf(g -> tick - g.tick > PENDING_TICKS);
		wornChanged.values().removeIf(t -> tick - t > WORN_TICKS);
		// Items for skills that take any item wait for the end of the tick, when a gear swap is known.
		match(true);
		Player player = client.getLocalPlayer();
		if (player == null || player.getLocalLocation() == null)
		{
			return;
		}
		WorldView wv = viewOf(player);
		overlay.setView(wv.getId(), wv.getPlane());
		LocalPoint at = player.getLocalLocation();
		boolean walkAway = config.clearWhen() == ImmersiveSkillingConfig.ClearWhen.WALK_AWAY;
		double fadeAfter = config.pileFade().getMinutes() * 60.0;
		double clock = seconds();
		Iterator<Pile> each = piles.iterator();
		while (each.hasNext())
		{
			Pile pile = each.next();
			double dist = Math.hypot(at.getX() - pile.x, at.getY() - pile.y) / TILE;
			// Boarding or leaving a boat moves you to another worldview, so the pile can't follow.
			boolean faded = fadeAfter > 0 && clock - pile.lastUsed > fadeAfter;
			if ((walkAway && dist > WALK_AWAY_TILES) || dist > FAR_TILES || wv.getPlane() != pile.plane || wv.getId() != pile.view
				|| faded)
			{
				props.dissolvePile(pile.id, seconds());
				each.remove();
				if (pile == lastPile)
				{
					lastPile = null;
					statusCount = 0;
					refreshPanel();
				}
			}
		}
		labelPiles(wv);
		watchSource(player, at, tick);
		syncRareLog();
		bagFallback(player, tick);
		ambient(player, tick);
	}

	/**
	 * WHAT: Plays the last item again when a gathering skill gave XP but nothing arrived.
	 * WHY: With a log basket, fish barrel or bag open, the item goes straight in, so there's no
	 * inventory change to match. Without this those players saw no effects at all.
	 * PRE: Client thread; called every tick, after the item for an XP drop would have arrived.
	 * POST: May play one effect per gathering skill.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	private void bagFallback(Player player, int tick)
	{
		for (Skill skill : BAG_SKILLS)
		{
			Integer xp = xpTick.get(skill);
			if (xp == null || tick - xp <= MATCH_TICKS || xp.equals(checkedXp.get(skill)))
			{
				continue;
			}
			checkedXp.put(skill, xp);
			Integer itemId = lastItem.get(skill);
			// A trawling net catches on its own, so on a boat you needn't be animating.
			boolean trawling = skill == Skill.FISHING && onBoat() && findObjectWithin(8, "trawling net") != null;
			// Filling a Tempoross crate gives Fishing XP, but nothing was caught.
			boolean handedIn = Math.abs(xp - depositTick) <= MATCH_TICKS;
			if (xp.equals(matchedXp.get(skill)) || handedIn || (player.getAnimation() == -1 && !trawling))
			{
				continue;
			}
			if (itemId == null || itemId <= 0)
			{
				// Nothing to replay yet: say why in the panel rather than showing nothing at all.
				if (carriesBag(skill))
				{
					setHint(bagHint(skill));
				}
				continue;
			}
			Activity activity = skill == Skill.WOODCUTTING ? Activity.WOODCUTTING
				: skill == Skill.FISHING ? Activity.FISHING : Activity.MINING;
			play(activity, itemId, client.getItemDefinition(itemId).getName(), Collections.emptyList(), null, 1);
		}
	}

