	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ImmersiveSkillingConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("showPanel".equals(event.getKey()) && navButton != null)
		{
			if (config.showPanel())
			{
				clientToolbar.addNavigation(navButton);
			}
			else
			{
				clientToolbar.removeNavigation(navButton);
			}
		}
		if (!config.enabled() || "logPile".equals(event.getKey()) || "catchBasket".equals(event.getKey())
			|| "oreChunks".equals(event.getKey()) || "harvestPile".equals(event.getKey()) || "pileSize".equals(event.getKey()))
		{
			clientThread.invokeLater(this::clearPile);
		}
		if (!config.enabled())
		{
			clientThread.invokeLater(this::clearAll);
		}
		refreshPanel();
	}

	// ---- Matching XP to items ---------------------------------------------------------------

	/**
	 * WHAT: Pairs each new item with the skill that gave XP in the same tick (or one apart),
	 * and plays the effect.
	 * WHY: An item alone could be a bank withdrawal; XP alone could be from anything. Together
	 * they say exactly what you just did.
	 * PRE: Client thread.
	 * POST: Matched items are played and removed from the pending list.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	private void match()
	{
		match(false);
	}

	/**
	 * WHAT: Matches waiting items to XP; with endOfTick false, skills that take any item wait.
	 * WHY: Fletching, Herblore, Crafting, Thieving, Farming and Hunter can't tell a product from an
	 * item you just took off, so they're matched once the tick's equipment change is in (issue #6).
	 * PRE: Client thread.
	 * POST: Matched items are played and removed from the pending list.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	private void match(boolean endOfTick)
	{
		if (pending.isEmpty() || xpTick.isEmpty())
		{
			return;
		}
		Iterator<Gain> it = pending.iterator();
		while (it.hasNext())
		{
			Gain gain = it.next();
			// Superheat also gives Smithing XP and String Jewellery Crafting XP, so a spell is
			// recognised first, whichever skill's XP is nearest.
			String spell = spellFor(gain);
			Skill skill = spell != null ? Skill.MAGIC : skillNear(gain.tick);
			if (skill == null || (!endOfTick && (spell != null || takesAnyItem(skill))))
			{
				continue;
			}
			Integer swapped = wornChanged.get(gain.itemId);
			if (swapped != null && Math.abs(swapped - gain.tick) <= WORN_TICKS)
			{
				// You took it off or put it on; you didn't make it.
				it.remove();
				continue;
			}
			String name = client.getItemDefinition(gain.itemId).getName();
			LocalPoint furnace = null;
			LocalPoint anvil = null;
			if (skill == Skill.SMITHING && !gain.used)
			{
				furnace = findObject("furnace");
				if (furnace == null)
				{
					// Blast Furnace bars are collected, with the XP, from the bar dispenser.
					furnace = findObject("bar dispenser");
				}
				anvil = findObject("anvil");
			}
			Activity activity = spell != null ? Activity.SPELLCASTING
				: skill == Skill.SAILING
				? (Activity.sailing(name, names(gain.lost), gain.used) != null ? Activity.SAILING : null)
				: gain.used ? Activity.classifyUsed(skill, name)
				: Activity.classify(skill, name, furnace != null, anvil != null);
			if (activity == null)
			{
				continue;
			}
			it.remove();
			matchedXp.put(skill, xpTick.get(skill));
			if (BAG_SKILLS.contains(skill))
			{
				rememberItem(skill, gain.itemId);
			}
			play(activity, gain.itemId, name, gain.lost, station(activity, furnace, anvil), gain.quantity);
		}
	}

	/**
	 * WHAT: Which item-changing spell an arrived item came from, if Magic XP came with it.
	 * WHY: Superheat, Plank Make, enchants and String Jewellery swap one item for another; see
	 * Activity.spell.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: the spell's kind, or null when it isn't one
	 * THROWS: Nothing.
	 */
	private String spellFor(Gain gain)
	{
		Integer magic = xpTick.get(Skill.MAGIC);
		if (gain.used || magic == null || Math.abs(magic - gain.tick) > MATCH_TICKS)
		{
			return null;
		}
		return Activity.spell(client.getItemDefinition(gain.itemId).getName(), names(gain.lost));
	}

	/**
	 * WHAT: Where an effect comes from: the furnace, anvil, fire, altar, or who you're stealing from.
	 * WHY: Bars come out of the furnace you use, runes out of the altar, loot out of the pocket.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: the place, or null to use the tile in front of you
	 * THROWS: Nothing.
	 */
	private LocalPoint station(Activity activity, LocalPoint furnace, LocalPoint anvil)
	{
		switch (activity)
		{
			case SMELTING:
				return furnace;
			case SMITHING:
				return anvil;
			case FIREMAKING:
				return findObject("fire", "brazier");
			case COOKING:
				return findRange();
			case RUNECRAFT:
			case PRAYER:
				// Bones go onto the altar beside you; with none, they're buried.
				return findObject("altar");
			case HUNTER:
			{
				Player player = client.getLocalPlayer();
				Actor target = player == null ? null : player.getInteracting();
				WorldView targetView = target == null ? null : target.getWorldView();
				if (targetView != null && targetView.getId() == viewOf(player).getId())
				{
					// Butterflies and implings are caught with a net in your hand.
					return target.getLocalLocation();
				}
				GameObject trap = workObject(client.getLocalPlayer().getLocalLocation(), "check", "dismantle", "reset");
				return trap != null ? trap.getLocalLocation() : findObject("trap", "snare", "net");
			}
			case THIEVING:
			{
				Player player = client.getLocalPlayer();
				Actor target = player == null ? null : player.getInteracting();
				if (target == null)
				{
					// Stalls and chests aren't someone you interact with; find the one beside you.
					GameObject stall = workObject(player.getLocalLocation(), "steal", "search", "pick");
					return stall != null ? stall.getLocalLocation() : findObject("stall", "chest");
				}
				// A point on another worldview (a boat and the shore) would land in the wrong place.
				WorldView targetView = target.getWorldView();
				return targetView == null || targetView.getId() != viewOf(player).getId() ? null : target.getLocalLocation();
			}
			default:
				return null;
		}
	}

	/**
	 * WHAT: Remembers the last item a gathering skill gave you, in the settings.
	 * WHY: So a basket or barrel gets effects even right after logging in.
	 * PRE: Client thread.
	 * POST: The item is saved when it changed.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	private void rememberItem(Skill skill, int itemId)
	{
		Integer before = lastItem.put(skill, itemId);
		if (before == null || before != itemId)
		{
			String key = skill == Skill.WOODCUTTING ? "lastWoodcutting" : skill == Skill.FISHING ? "lastFishing" : "lastMining";
			configManager.setConfiguration(ImmersiveSkillingConfig.GROUP, key, itemId);
		}
	}

	private Skill skillNear(int tick)
	{
		Skill best = null;
		int bestGap = Integer.MAX_VALUE;
		for (Map.Entry<Skill, Integer> e : xpTick.entrySet())
		{
			int gap = Math.abs(e.getValue() - tick);
			// Cooking is off by default; while it is, Cooking XP is ignored entirely.
			boolean on = e.getKey() != Skill.COOKING || cookingOn();
			if (gap <= MATCH_TICKS && gap < bestGap && isShown(e.getKey()) && on)
			{
				best = e.getKey();
				bestGap = gap;
			}
		}
		return best;
	}

	/** An item that went on or came off within this many ticks of arriving is a gear swap. */
	static final int WORN_TICKS = 2;

	/**
	 * WHAT: Whether a skill counts any item that arrives as its product.
	 * WHY: These can't tell a product from a swapped item by name, so they wait for the tick to end.
	 * PRE: None.
	 * POST: Nothing changes.
	 * RETURN: true for Fletching, Thieving, Herblore, Crafting, Farming, Hunter and Sailing (sorting)
	 * THROWS: Nothing.
	 */
	static boolean takesAnyItem(Skill skill)
	{
		return skill == Skill.FLETCHING || skill == Skill.THIEVING || skill == Skill.HERBLORE || skill == Skill.CRAFTING
			|| skill == Skill.FARMING || skill == Skill.HUNTER || skill == Skill.SAILING || skill == Skill.COOKING;
	}

	/**
	 * WHAT: Whether an item that arrived is just a potion with one dose fewer, or the empty vial.
	 * WHY: Drinking a Prayer potion(4) leaves a Prayer potion(3); that isn't Herblore (issue #6).
	 * PRE: lost holds the names of what left the inventory in the same change; either may hold nulls.
	 * POST: Nothing changes.
	 * RETURN: true for a sip
	 * THROWS: Nothing.
	 */
	static boolean isSip(String gained, List<String> lost)
	{
		if (gained == null || lost == null)
		{
			return false;
		}
		java.util.regex.Matcher g = DOSE.matcher(gained);
		for (String name : lost)
		{
			java.util.regex.Matcher l = name == null ? null : DOSE.matcher(name);
			if (l == null || !l.matches())
			{
				continue;
			}
			if (g.matches() && g.group(1).equals(l.group(1)) && Integer.parseInt(g.group(2)) < Integer.parseInt(l.group(2)))
			{
				return true;
			}
			if (gained.equals("Vial") && l.group(2).equals("1"))
			{
				return true;
			}
		}
		return false;
	}

	private static final java.util.regex.Pattern DOSE = java.util.regex.Pattern.compile("(.+)\\((\\d)\\)");

	static boolean isShown(Skill skill)
	{
		return skill == Skill.WOODCUTTING || skill == Skill.FISHING || skill == Skill.MINING || skill == Skill.SMITHING
			|| skill == Skill.FLETCHING || skill == Skill.FIREMAKING || skill == Skill.RUNECRAFT || skill == Skill.THIEVING
			|| skill == Skill.HERBLORE || skill == Skill.CRAFTING || skill == Skill.PRAYER || skill == Skill.MAGIC
			|| skill == Skill.FARMING || skill == Skill.HUNTER || skill == Skill.AGILITY || skill == Skill.CONSTRUCTION
			|| skill == Skill.SAILING || skill == Skill.COOKING;
	}

	/**
	 * WHAT: The names of the given items.
	 * WHY: Sailing is told apart by what left the inventory with an item.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: the names, in the same order
	 * THROWS: Nothing.
	 */
	private List<String> names(List<Integer> ids)
	{
		List<String> out = new ArrayList<>();
		for (int id : ids)
		{
			out.add(client.getItemDefinition(id).getName());
		}
		return out;
	}

	private static Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	/**
	 * WHAT: The nearest object within 3 tiles whose name contains one of the given words, e.g. "anvil".
	 * WHY: Hot bars appear at the furnace you're using and items on the anvil you're using.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: its location, or null if there isn't one nearby
	 * THROWS: Nothing.
	 */
	private LocalPoint findObject(String... words)
	{
		return findObjectWithin(3, words);
	}

	/**
	 * WHAT: Like findObject, but within the given number of tiles.
	 * WHY: Your salvaging hook or trawling net can be at the far end of a long boat.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: its location, or null if there isn't one in reach
	 * THROWS: Nothing.
	 */
	private LocalPoint findObjectWithin(int reach, String... words)
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getLocalLocation() == null)
		{
			return null;
		}
		WorldView wv = viewOf(player);
		Scene scene = wv.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = wv.getPlane();
		int px = player.getLocalLocation().getSceneX();
		int py = player.getLocalLocation().getSceneY();
		LocalPoint best = null;
		int bestDist = Integer.MAX_VALUE;
		for (int x = px - reach; x <= px + reach; x++)
		{
			for (int y = py - reach; y <= py + reach; y++)
			{
				if (x < 0 || y < 0 || x >= tiles[plane].length || y >= tiles[plane][x].length || tiles[plane][x][y] == null)
				{
					continue;
				}
				for (GameObject object : tiles[plane][x][y].getGameObjects())
				{
					if (object == null)
					{
						continue;
					}
					ObjectComposition def = client.getObjectDefinition(object.getId());
					if (def != null && def.getImpostorIds() != null)
					{
						def = def.getImpostor();
					}
					String name = def == null ? null : def.getName();
					if (name != null && containsAny(name.toLowerCase(java.util.Locale.ROOT), words))
					{
						int dist = Math.abs(x - px) + Math.abs(y - py);
						if (dist < bestDist)
						{
							bestDist = dist;
							best = object.getLocalLocation();
						}
					}
				}
			}
		}
		return best;
	}

	/**
	 * WHAT: The worldview you're standing on: the main world, or your Sailing boat.
	 * WHY: On a boat your position is on the boat's own worldview. Effects placed in the main
	 * world from that position landed somewhere out at sea, so boat fishing showed nothing.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: the player's worldview, or the main one if the player has none
	 * THROWS: Nothing.
	 */
	private WorldView viewOf(Player player)
	{
		WorldView wv = player == null ? null : player.getWorldView();
		return wv != null ? wv : client.getTopLevelWorldView();
	}

	private static boolean containsAny(String name, String[] words)
	{
		for (String word : words)
		{
			if (name.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	// ---- Effects ----------------------------------------------------------------------------

	/**
	 * WHAT: Plays the effect for one item made by an activity.
	 * WHY: The heart of the plugin: decides which props fly where and which particles burst.
	 * PRE: Client thread. station is the furnace, anvil, fire, altar or loot source, or null.
	 * quantity is how many arrived (or were used), for the pop.
	 * POST: Props and particles are added; the panel status is updated.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	void play(Activity activity, int itemId, String itemName, List<Integer> lost, LocalPoint station, int quantity)
	{
		if (!config.enabled() || paused || props == null)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getLocalLocation() == null)
		{
			return;
		}
		WorldView wv = viewOf(player);
		int plane = wv.getPlane();
		overlay.setView(wv.getId(), plane);
		props.setView(wv.getId());
		LocalPoint at = player.getLocalLocation();
		double angle = player.getCurrentOrientation() * Math.PI * 2 / 2048;
		double fx = -Math.sin(angle);
		double fy = -Math.cos(angle);
		double tx = at.getX() + fx * TILE;
		double ty = at.getY() + fy * TILE;
		double now = seconds();
		double amount = config.amount().getScale();
		Particles particles = overlay.getParticles();

		setHint("");
		// Now and then a rare moment: the item turns gold and a flourish of light plays.
		boolean rare = rollRare();
		props.setGolden(rare);
		lastActivity = activity;
		lastActivityTime = now;
		targetX = station != null ? station.getX() : tx;
		targetY = station != null ? station.getY() : ty;
		lastStandPoint = at;
		// Where a gathered resource really comes from: the trunk, the rock face, the fishing spot,
		// the patch. {x, y} on the side facing you, then the object's middle.
		double[] src = source(activity, at, tx, ty);
		if (activity.isGathering())
		{
			targetX = src[0];
			targetY = src[1];
		}
		String popText = popText(activity, quantity, itemName);

		switch (activity)
		{
			case WOODCUTTING:
				if (config.woodChips())
				{
					// Chips fly off the trunk where your axe bites; leaves fall from the canopy.
					particles.burst(Particles.Kind.CHIP, src[0], src[1], 70, 10, amount);
					particles.burst(Particles.Kind.FALLING_LEAF, src[2], src[3], 230, 3, amount);
				}
				if (config.logPile())
				{
					// The log drops from the trunk and tumbles onto the pile.
					addToPile(activity, itemId, at, fx, fy, plane, src[0], src[1], src[2], src[3], (int) src[4], 90, 60, now);
				}
				break;
			case FISHING:
				if (config.splashes())
				{
					// The catch leaps out of the fishing spot itself, with a splash and rings.
					particles.burst(Particles.Kind.DROPLET, src[0], src[1], 0, 12, amount);
					particles.single(Particles.Kind.RIPPLE, src[0], src[1], 0, 0xDCF0FF, 70, 1.0);
					particles.single(Particles.Kind.RIPPLE, src[0], src[1], 0, 0xDCF0FF, 120, 1.4);
				}
				if (config.catchBasket())
				{
					addToPile(activity, itemId, at, fx, fy, plane, src[0], src[1], src[2], src[3], (int) src[4], 10, 130, now);
				}
				break;
			case MINING:
				if (config.dustSparks())
				{
					// The rock face takes the hit: dust, sparks and chips fly from it.
					particles.burst(Particles.Kind.DUST, src[0], src[1], 50, 6, amount);
					particles.burst(Particles.Kind.SPARK, src[0], src[1], 60, 10, amount);
					particles.burst(Particles.Kind.STONE, src[0], src[1], 55, 6, amount);
				}
				if (config.oreChunks())
				{
					// The ore breaks off the face and bounces onto the heap.
					addToPile(activity, itemId, at, fx, fy, plane, src[0], src[1], src[2], src[3], (int) src[4], 45, 60, now);
				}
				break;
			case SMELTING:
				smelt(itemId, lost, station, at, plane, now, amount);
				break;
			case SMITHING:
			{
				// The bars go from your pack onto the anvil, then the item takes shape on it.
				double d = ingredients(lost, at, station != null ? station.getX() : tx, station != null ? station.getY() : ty,
					station != null ? 75 : 45, plane, now);
				smith(itemId, station, tx, ty, plane, now + d, amount);
			}
				break;
			case FIREMAKING:
				firemake(itemId, station, at, fx, fy, plane, now, amount);
				break;
			case COOKING:
				cook(itemId, station, at, fx, fy, plane, now, amount);
				break;
			case RUNECRAFT:
				runecraft(itemId, quantity, station, tx, ty, plane, now, amount);
				break;
			case THIEVING:
				thieve(itemId, station, at, tx, ty, plane, now, amount);
				break;
			case HERBLORE:
				// The herb and vial (or the unfinished potion and its secondary) go in first.
				herblore(itemId, itemName, at, fx, fy, plane,
					now + ingredients(lost, at, at.getX() + fx * 80, at.getY() + fy * 80, 60, plane, now), amount);
				break;
			case CRAFTING:
				craft(itemId, itemName, at, fx, fy, plane,
					now + ingredients(lost, at, at.getX() + fx * 80, at.getY() + fy * 80, 60, plane, now), amount);
				break;
			case PRAYER:
				pray(itemId, itemName, station, at, fx, fy, plane, now, amount);
				break;
			case ALCHING:
				alch(itemId, lost, at, plane, now, amount);
				break;
			case SPELLCASTING:
				cast(itemId, itemName, lost, at, plane, now, amount);
				break;
			case FARMING:
				if (config.soilPuffs())
				{
					particles.burst(Particles.Kind.SOIL, src[0], src[1], 10, 10, amount);
				}
				if (config.harvestPile())
				{
					// Pulled out of the patch, it pops up and drops onto the heap.
					addToPile(activity, itemId, at, fx, fy, plane, src[0], src[1], src[2], src[3], (int) src[4], 15, 80, now);
				}
				break;
			case HUNTER:
				hunt(itemId, station, at, tx, ty, plane, now, amount);
				break;
			case CONSTRUCTION:
				build(itemId, at, tx, ty, plane, now, amount);
				break;
			case SAILING:
				sail(itemId, itemName, lost, at, fx, fy, plane, now, amount);
				break;
			default:
				fletch(itemId, at, fx, fy, plane,
					now + ingredients(lost, at, at.getX() + fx * 80, at.getY() + fy * 80, 60, plane, now), amount);
				break;
		}
		if (config.itemPops())
		{
			// Loot is shown over you, where it lands; the rest where it was made.
			boolean overYou = activity == Activity.THIEVING || activity == Activity.ALCHING || activity == Activity.HUNTER
				|| activity == Activity.SPELLCASTING;
			boolean onPile = lastPile != null && lastPile.activity == activity && lastPile.lastUsed == now;
			double popX = onPile ? lastPile.x : overYou ? at.getX() : targetX;
			double popY = onPile ? lastPile.y : overYou ? at.getY() : targetY;
			overlay.addPop(new EffectsOverlay.Pop(itemId, popText, popX, popY, plane, now));
		}
		props.setGolden(false);
		if (rare)
		{
			rareFlourish(activity, itemName, at, plane, now, amount);
		}
		updateStatus(activity);
	}

	private void addToPile(Activity activity, int itemId, LocalPoint at, double fx, double fy, int plane,
		double fromX, double fromY, double midX, double midY, int size, double fromZ, double peak, double now)
	{
		int cap = config.pileSize().getCount();
		boolean boat = onBoat();
		String key = pileKey(activity, boat, size, midX, midY, plane, props.getView());
		Pile pile = null;
		for (Pile each : piles)
		{
			if (each.key.equals(key))
			{
				pile = each;
			}
		}
		if (pile == null)
		{
			pile = newPile(activity, key, at, fx, fy, plane, midX, midY, size, boat, now);
		}
		pile.lastUsed = now;
		pile.name = client.getItemDefinition(itemId).getName();
		lastPile = pile;
		PileLayout.Shape shape = activity == Activity.FISHING ? PileLayout.Shape.BASKET
			: activity == Activity.WOODCUTTING ? PileLayout.Shape.STACK : PileLayout.Shape.HEAP;
		boolean full = pile.count >= cap;
		// A full pile still takes the new item: it lands on top, then sinks in.
		int[] slot = PileLayout.slot(shape, full ? cap - 1 : pile.count, cap);
		double angle = pile.yaw * Math.PI * 2 / 2048;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double toX = pile.x + (slot[0] * cos - slot[1] * sin) * pile.spread;
		double toY = pile.y + (slot[0] * sin + slot[1] * cos) * pile.spread;
		double toZ = slot[2] + (full ? PileLayout.LAYER_HEIGHT : 0);
		int orientation = (slot[3] + pile.yaw) & 2047;
		// Everything already on this pile hops as the new item lands.
		props.nudgePile(pile.id, now + 0.5);
		Model model = props.itemModel(itemId, 128, 0);
		Props.Prop p = props.launch(model, full ? Props.Group.FLOATING : Props.Group.PILE, plane, fromX, fromY, fromZ, toX, toY,
			toZ, peak, 0.55, true, orientation, now);
		if (p == null)
		{
			return;
		}
		Props.resize(p, itemId, 128, 0, full ? 0.35 : 0);
		if (full)
		{
			p.expires = now + 1.0;
		}
		else
		{
			p.pile = pile.id;
			pile.count++;
		}
	}

	/**
	 * WHAT: Which pile an item goes on: one per resource (the tree, rock, fishing spot or patch's
	 * tile), one shared pile when no resource was found, and one on your own tile on a boat.
	 * WHY: Each resource keeps its own pile instead of everything landing in one place.
	 * PRE: size is the resource's width in tiles, or 0 when none was found.
	 * POST: Nothing changes.
	 * RETURN: the key; items with the same key share a pile
	 * THROWS: Nothing.
	 */
	static String pileKey(Activity activity, boolean boat, int size, double midX, double midY, int plane, int view)
	{
		if (boat)
		{
			return activity + ":boat:" + view;
		}
		if (size <= 0)
		{
			return activity + ":here:" + plane + ":" + view;
		}
		return activity + ":" + (int) Math.floor(midX / TILE) + "," + (int) Math.floor(midY / TILE) + ":" + plane + ":" + view;
	}

	/**
	 * WHAT: Starts a new pile: beside its resource on land, on your own tile on a boat, or behind
	 * you when the resource wasn't found.
	 * WHY: Several piles can be out at once; past MAX_PILES the oldest shrinks away first.
	 * PRE: Client thread.
	 * POST: The pile is in the list (and a basket is out for fishing).
	 * RETURN: the new pile
	 * THROWS: Nothing.
	 */
	private Pile newPile(Activity activity, String key, LocalPoint at, double fx, double fy, int plane, double midX,
		double midY, int size, boolean boat, double now)
	{
		if (piles.size() >= MAX_PILES)
		{
			Pile oldest = piles.get(0);
			for (Pile each : piles)
			{
				if (each.lastUsed < oldest.lastUsed)
				{
					oldest = each;
				}
			}
			props.dissolvePile(oldest.id, now);
			piles.remove(oldest);
		}
		double[] spot = null;
		if (boat)
		{
			// On a boat, your own tile, so it stays on the deck of every boat from a raft up
			// (issue #2: on a raft the tile behind you is the sea).
			spot = boatPileSpot(at.getX(), at.getY(), fx, fy);
		}
		else if (size > 0)
		{
			spot = besideResource(at, midX, midY, size);
		}
		if (spot == null)
		{
			// A free tile beside and behind you: never in a wall, a tree or the water.
			spot = pileSpot(at, fx, fy);
		}
		Player player = client.getLocalPlayer();
		int yaw = player == null ? 0 : player.getCurrentOrientation();
		Pile pile = new Pile(nextPileId++, activity, key, spot[0], spot[1], plane, props.getView(), yaw, boat ? BOAT_SPREAD : 1);
		piles.add(pile);
		if (activity == Activity.FISHING)
		{
			Model basket = props.itemModel(ItemID.BASKET_EMPTY, 200, 0);
			Props.Prop b = props.launch(basket, Props.Group.BASKET, plane, pile.x, pile.y, 0, pile.x, pile.y, 0, 0, 0.01, false,
				yaw, now);
			if (b != null)
			{
				b.golden = false;
				b.pile = pile.id;
				// The basket pops into place.
				Props.resize(b, ItemID.BASKET_EMPTY, 200, 0.25, 0);
			}
		}
		return pile;
	}

	/**
	 * WHAT: The middle of a free tile right beside a resource, nearest you, not used by another pile.
	 * WHY: The tree's logs pile up at that tree; the next tree gets its own pile.
	 * PRE: Client thread. (midX, midY) is the resource's middle in local units.
	 * POST: Nothing changes.
	 * RETURN: {x, y} in local units, or null if no tile beside it is free
	 * THROWS: Nothing.
	 */
	/**
	 * WHAT: The way you're facing, as a unit vector in local units.
	 * WHY: Smithing and smelting piles need it, and those effects aren't given it.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: {x, y}
	 * THROWS: Nothing.
	 */
	private double[] facing()
	{
		Player player = client.getLocalPlayer();
		double angle = player == null ? 0 : player.getCurrentOrientation() * Math.PI * 2 / 2048;
		return new double[]{-Math.sin(angle), -Math.cos(angle)};
	}

	private double[] besideResource(LocalPoint at, double midX, double midY, int size)
	{
		WorldView wv = viewOf(client.getLocalPlayer());
		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return null;
		}
		int[][] flags = maps[plane].getFlags();
		java.util.Set<Long> taken = new java.util.HashSet<>();
		for (Pile each : piles)
		{
			taken.add(PileLayout.key((int) Math.floor(each.x / TILE), (int) Math.floor(each.y / TILE)));
		}
		int[] tile = PileLayout.tileBeside(midX, midY, size, at.getSceneX(), at.getSceneY(),
			(x, y) -> x < 0 || y < 0 || x >= flags.length || y >= flags[x].length
				|| (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0, taken);
		return tile == null ? null : new double[]{tile[0] * TILE + TILE / 2.0, tile[1] * TILE + TILE / 2.0};
	}

	/**
	 * WHAT: What you used flies from you into what you're making: bars onto the anvil, the herb
	 * and vial into the potion, logs under the knife, the uncut gem under the chisel.
	 * WHY: The product appearing out of nothing skipped half the story; now you see the
	 * ingredients go in, then the product come out.
	 * PRE: Client thread. lost holds what left your inventory; (x, y, z) is where the product
	 * appears, z above the ground.
	 * POST: Up to two small props are added.
	 * RETURN: how long until they arrive, in seconds (0 when nothing went in), so the product can
	 * appear just as they do
	 * THROWS: Nothing.
	 */
	private double ingredients(List<Integer> lost, LocalPoint at, double x, double y, double z, int plane, double now)
	{
		int shown = 0;
		for (int id : lost)
		{
			if (shown >= 2)
			{
				break;
			}
			Props.Prop p = props.launch(props.itemModel(id, 90, 0), Props.Group.FLOATING, plane, at.getX(), at.getY(), 70, x, y, z,
				30, 0.28, false, 0, now + shown * 0.06);
			if (p != null)
			{
				// Only the product of a rare moment turns gold, not what went into it.
				p.golden = false;
				p.spinPerSecond = 500;
				p.expires = now + 0.28 + shown * 0.06;
				Props.resize(p, id, 90, 0.08, 0.1);
				shown++;
			}
		}
		return shown == 0 ? 0 : 0.3 + (shown - 1) * 0.06;
	}

	/**
	 * WHAT: Where a gathered resource comes from: the edge of the tree, rock or patch you're
	 * working (on your side), or the fishing spot you're fishing.
	 * WHY: Everything used to start from the tile in front of you; a big yew's trunk or a
	 * fishing spot two tiles out are somewhere else.
	 * PRE: Client thread. (tx, ty) is the tile in front of you, used if nothing is found.
	 * POST: Nothing changes.
	 * RETURN: {x, y, middleX, middleY, size in tiles (0 when nothing was found)} in local units
	 * THROWS: Nothing.
	 */
	private double[] source(Activity activity, LocalPoint at, double tx, double ty)
	{
		switch (activity)
		{
			case FISHING:
			{
				Player player = client.getLocalPlayer();
				Actor spot = player == null ? null : player.getInteracting();
				WorldView spotView = spot == null ? null : spot.getWorldView();
				if (spotView != null && spotView.getId() == viewOf(player).getId() && spot.getLocalLocation() != null)
				{
					LocalPoint s = spot.getLocalLocation();
					return new double[]{s.getX(), s.getY(), s.getX(), s.getY(), 1};
				}
				// Trawling from a boat: the catch comes up out of your net.
				LocalPoint net = onBoat() ? findObjectWithin(8, "trawling net") : null;
				return net != null ? new double[]{net.getX(), net.getY(), net.getX(), net.getY(), 1} : new double[]{tx, ty, tx, ty, 0};
			}
			default:
				break;
		}
		String[] actions = actionsFor(activity);
		double[] found = actions == null ? null : resourceAt(at, actions);
		if (found != null)
		{
			rememberSource(activity, at, found);
			return found;
		}
		// Gauntlet deposits and roots, and most rocks, run out on the tick your item arrives, so
		// the resource is gone; use the one you were just working on (or every last item from
		// every rock landed on one shared pile).
		boolean same = sourceSeen != null && sourceActivity == activity && at.equals(sourceStand)
			&& client.getTickCount() - sourceTick <= SOURCE_TICKS;
		return same ? sourceSeen : new double[]{tx, ty, tx, ty, 0};
	}

	/**
	 * WHAT: The right-click actions of the resource an activity gathers from.
	 * WHY: Trees say "Chop down" (Gauntlet roots "Cut"), rocks "Mine", patches "Harvest" or "Pick".
	 * PRE: None.
	 * POST: Nothing changes.
	 * RETURN: the lower case action starts, or null when the activity has no such resource
	 * THROWS: Nothing.
	 */
	static String[] actionsFor(Activity activity)
	{
		switch (activity)
		{
			case WOODCUTTING:
				return new String[]{"chop", "cut"};
			case MINING:
				return new String[]{"mine"};
			case FARMING:
				return new String[]{"harvest", "pick", "dig"};
			default:
				return null;
		}
	}

	/**
	 * WHAT: The resource beside you with one of the actions: the side facing you, its middle, its size.
	 * WHY: Shared by source() and the watch kept while you work.
	 * PRE: Client thread.
	 * POST: Nothing changes.
	 * RETURN: {x, y, middle x, middle y, size}, or null when there isn't one
	 * THROWS: Nothing.
	 */
	private double[] resourceAt(LocalPoint at, String[] actions)
	{
		GameObject object = workObject(at, actions);
		if (object == null || object.getLocalLocation() == null)
		{
			return null;
		}
		double cx = object.getLocalLocation().getX();
		double cy = object.getLocalLocation().getY();
		int size = Math.max(1, Math.max(object.sizeX(), object.sizeY()));
		double[] e = edge(cx, cy, size, at.getX(), at.getY());
		return new double[]{e[0], e[1], cx, cy, size};
	}

	private void rememberSource(Activity activity, LocalPoint at, double[] found)
	{
		sourceActivity = activity;
		sourceSeen = found;
		sourceStand = at;
		sourceTick = client.getTickCount();
	}

	/**
	 * WHAT: While you keep chopping, mining or picking, remembers the resource you're at.
	 * WHY: A rock that gives one ore is gone by the time that ore arrives; this saw it a tick before.
	 * PRE: Client thread; called every tick.
	 * POST: The remembered resource may be updated.
	 * RETURN: Nothing.
	 * THROWS: Nothing.
	 */
	private void watchSource(Player player, LocalPoint at, int tick)
	{
		String[] actions = lastActivity == null ? null : actionsFor(lastActivity);
		if (actions == null || player.getAnimation() == -1 || tick - xpTick.getOrDefault(lastActivity == Activity.MINING
			? Skill.MINING : lastActivity == Activity.FARMING ? Skill.FARMING : Skill.WOODCUTTING, -100) > 100)
		{
			return;
		}
		double[] found = resourceAt(at, actions);
		if (found != null)
		{
			rememberSource(lastActivity, at, found);
		}
	}

	/**
	 * WHAT: Hands the overlay a label for each pile you can see: how many, and of what.
	 * WHY: Hovering a pile tells you how much you've gathered there.
	 * PRE: Client thread; called every tick.
