				item.spinSettle = 0.5;
				// Then into your pack: it flies to you and shrinks away.
				Props.then(item, now + 1.15, at.getX(), at.getY(), 80, 30, 0.4);
				item.expires = now + 1.55;
				Props.resize(item, itemId, 128, 0.2, 0.2);
			}
